node --input-type=module <<'NODE'
import { registerHooks } from 'node:module';
import { existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
registerHooks({
  resolve(specifier, context, next) {
    if (context.parentURL?.startsWith('file:') && specifier.startsWith('.') && specifier.endsWith('.js')) {
      const candidate = new URL(specifier.slice(0, -3) + '.ts', context.parentURL);
      if (existsSync(fileURLToPath(candidate))) return next(candidate.href, context);
    }
    return next(specifier, context);
  },
});
const { loadVendorFile } = await import('./tools/node-vendor.mjs');
for (const path of ['compiler/typed/tape.js', 'compiler/typed/typed-wasm.js', 'bench/host/rv32-interp.js', ...['typed-rv32.js', 'typed-rv32-inline.js', 'typed-rv32-loops.js', 'typed-rv32-kernel.js'].map(x => 'compiler/typed/' + x)]) loadVendorFile(path);
const { setVendor } = await import('./src/typed/vendor.ts');
setVendor({ typedTape, typedWasm, typedRv32Interp, typedRv32 });
const { Program } = await import('./src/typed/program.ts');
const { projectSource } = await import('./src/typed/project.ts');
const { lowerToImage, imageFromCode, runImage } = await import('./src/typed/backend/index.ts');
const { benchCase } = await import('./src/typed/evaluate.ts');
const { storeOf } = await import('./src/typed/ir.ts');
const files = {
  'helper.typed': 'function readCell(pos: buffer, i: i32): i32 { return pos.charCodeAt(i); }',
  'main.typed': 'function sample(pos: buffer, work: buffer, d: i32): i32 { const stack = new Int32Array(3); let i = 0; while (i < d) { stack[i] = readCell(pos, i); work.setCharCodeAt(i, stack[i]); i = i + 1; } return stack[0]; }',
  'project.json': JSON.stringify({sources:['helper.typed','main.typed'],pipeline:'speed',inputs:{sample:{pos:{cells:[17,23]},work:{buffer:[2,2],cell:[0,0]},d:{oneOf:[1,2]}}}})
};
const ps = projectSource('probe', files);
const p = new Program(ps.name, ps.source, {inputs:ps.meta.inputs,entries:['sample']});
if (p.status !== 'ok') throw Error(JSON.stringify(p.error));
const c = benchCase(storeOf(p.origin.value), 'sample', {pos:{cells:[17,23]},work:{cells:[0,0]},d:2});
const ref = typedRv32.compile(ps.source, [], undefined);
const refImage = imageFromCode('probe',ref.image,ref.entries);
const original = p.exec('sample', [[17,23],[0,0],2], {limit:20000});
const steps = await p.pipeline('speed');
const checks = p.check({against:(fn,k)=>runImage(refImage,fn,k.args,k.memory,{limit:200000})});
const rv = runImage(lowerToImage(p.head).image, c.fn,c.args,c.memory,{limit:200000});
if (original.result !== 17 || original.buffers[1].cells.join() !== '17,23' || rv.result !== 17 || rv.trap || checks.fns.some(f=>f.agree!==100 || f.inconclusive) || steps.some(s=>s.rejected)) throw Error(JSON.stringify({original,rv,steps,checks}));
console.log(JSON.stringify({original,rv:{steps:rv.steps,result:rv.result}, checks:checks.fns,passesChanged:steps.filter(s=>s.changed).map(s=>s.pass)}));
NODE
